30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "telephone")
50	    @NotEmpty
51	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    @Email
56	    private String email;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "postcode")
65	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
66	    private String postcode;
67	
68	    @Column(name = "customer_code")
69	    private String customerCode;
70	
71	    @Column(name = "household_id")
72	    private String householdId;
73	
74	    @Column(name = "namesake_count")
75	    private Integer namesakeCount;
76	
77	    @Column(name = "bulk_signup_warning")
78	    private Boolean bulkSignupWarning;
79	
80	    @Column(name = "household_size")
81	    private Integer householdSize;
82	
83	    @Column(name = "possible_duplicate")
84	    private Boolean possibleDuplicate;
85	
86	    @Column(name = "possible_duplicate_of")
87	    private Integer possibleDuplicateOf;
88	
89	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
90	    private Set<Pet> pets;
91	
92	    /** Common street-type abbreviations expanded during address normalization. */
93	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
94	        "ST", "STREET",
95	        "RD", "ROAD",
96	        "AVE", "AVENUE");
97	
98	    /** Fixed city-to-region table used to derive an owner's locality. */
99	    private static final Map<String, String> CITY_REGION = Map.of(
100	        "Sydney", "NSW",
101	        "Melbourne", "VIC",
102	        "Brisbane", "QLD");
103	
104	    /** Fixed region-to-postcode-range table (inclusive) used to validate a postcode. */
105	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
106	        "NSW", new int[] {2000, 2099},
107	        "VIC", new int[] {3000, 3099},
108	        "QLD", new int[] {4000, 4099});
109	
110	    /** Fixed region-to-timezone table (IANA names) used to derive an owner's timezone. */
111	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
112	        "NSW", "Australia/Sydney",
113	        "VIC", "Australia/Melbourne",
114	        "QLD", "Australia/Brisbane");
115	
116	    public String getAddress() {
117	        return this.address;
118	    }
119	
120	    /**
121	     * Set the owner's address, normalizing it to a canonical form so it is both
122	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
123	     * internal runs of whitespace are collapsed to a single space, the value is
124	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
125	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
126	     * left as-is.
127	     */
128	    public void setAddress(String address) {
129	        this.address = normalizeAddress(address);
130	    }
131	
132	    /**
133	     * Normalize an address string to its canonical form: trimmed, whitespace
134	     * collapsed, upper-cased, with common street-type abbreviations expanded.
135	     * Returns {@code null} for a {@code null} input; a value that is blank once
136	     * trimmed normalizes to the empty string.
137	     */
138	    public static String normalizeAddress(String address) {
139	        if (address == null) {
140	            return null;
141	        }
142	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
143	        if (collapsed.isEmpty()) {
144	            return "";
145	        }
146	        String[] tokens = collapsed.split(" ");
147	        StringBuilder sb = new StringBuilder();
148	        for (int i = 0; i < tokens.length; i++) {
149	            if (i > 0) {
150	                sb.append(' ');
151	            }
152	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
153	        }
154	        return sb.toString();
155	    }
156	
157	    public String getCity() {
158	        return this.city;
159	    }
160	
161	    public void setCity(String city) {
162	        this.city = city;
163	    }
164	
165	    public String getTelephone() {
166	        return this.telephone;
167	    }
168	
169	    public void setTelephone(String telephone) {
170	        this.telephone = telephone;
171	    }
172	
173	    /**
174	     * Return the stored E.164 telephone formatted for humans: a {@code '+'} and the
175	     * country code, a space, then the national digits grouped in threes and separated
176	     * by single spaces (for example {@code '+61412345678' -> '+61 412 345 678'}). The
177	     * North American country code ({@code '+1'}) is one digit; other country codes are
178	     * taken as two. Returns {@code null} when the telephone is not set, and returns the
179	     * raw value unchanged when it is not a well-formed E.164 number.
180	     */
181	    public String getTelephoneDisplay() {
182	        if (this.telephone == null || !this.telephone.matches("^\\+[0-9]+$")) {
183	            return this.telephone;
184	        }
185	        String digits = this.telephone.substring(1);
186	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
187	        if (digits.length() <= countryCodeLength) {
188	            return this.telephone;
189	        }
190	        String countryCode = digits.substring(0, countryCodeLength);
191	        String national = digits.substring(countryCodeLength);
192	        StringBuilder sb = new StringBuilder("+").append(countryCode);
193	        for (int i = 0; i < national.length(); i += 3) {
194	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
195	        }
196	        return sb.toString();
197	    }
198	
199	    public String getEmail() {
200	        return this.email;
201	    }
202	
203	    /**
204	     * Set the owner's email address, normalizing it to lower case so it is both
205	     * stored and returned in a canonical form. A {@code null} value is left as-is.
206	     */
207	    public void setEmail(String email) {
208	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
209	    }
210	
211	    public LocalDate getRegistrationDate() {
212	        return this.registrationDate;
213	    }
214	
215	    public void setRegistrationDate(LocalDate registrationDate) {
216	        this.registrationDate = registrationDate;
217	    }
218	
219	    public LocalDate getBirthDate() {
220	        return this.birthDate;
221	    }
222	
223	    public void setBirthDate(LocalDate birthDate) {
224	        this.birthDate = birthDate;
225	    }
226	
227	    /**
228	     * Return the owner's age band derived from the birth date, computed against the
229	     * registration date: {@code 'MINOR'} when under 18, {@code 'ADULT'} when 18 to
230	     * 64 inclusive, and {@code 'SENIOR'} when 65 or older. Returns {@code null} when
231	     * either the birth date or the registration date is not set.
232	     */
233	    public String getAgeBand() {
234	        if (this.birthDate == null || this.registrationDate == null) {
235	            return null;
236	        }
237	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
238	        if (age < 18) {
239	            return "MINOR";
240	        }
241	        if (age < 65) {
242	            return "ADULT";
243	        }
244	        return "SENIOR";
245	    }
246	
247	    public String getPostcode() {
248	        return this.postcode;
249	    }
250	
251	    public void setPostcode(String postcode) {
252	        this.postcode = postcode;
253	    }
254	
255	    /**
256	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
257	     * is always valid (postcode is optional). When present, a postcode is valid if
258	     * the city has no known region, or if it is four digits falling within the
259	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
260	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
261	     */
262	    public boolean isPostcodeValidForCity() {
263	        if (this.postcode == null) {
264	            return true;
265	        }
266	        String region = CITY_REGION.get(this.city);
267	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
268	        if (range == null) {
269	            return true;
270	        }
271	        if (!this.postcode.matches("^[0-9]{4}$")) {
272	            return false;
273	        }
274	        int value = Integer.parseInt(this.postcode);
275	        return value >= range[0] && value <= range[1];
276	    }
277	
278	    public String getCustomerCode() {
279	        return this.customerCode;
280	    }
281	
282	    public void setCustomerCode(String customerCode) {
283	        this.customerCode = customerCode;
284	    }
285	
286	    /**
287	     * Return a single Luhn check digit (0-9) computed over the digits contained in
288	     * the owner's customer code, or {@code null} when the customer code is not set.
289	     * Non-digit characters in the code are ignored; the rightmost digit is doubled
290	     * first, following the standard Luhn algorithm.
291	     */
292	    public Integer getCheckDigit() {
293	        if (this.customerCode == null) {
294	            return null;
295	        }
296	        int sum = 0;
297	        boolean doubleDigit = true;
298	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
299	            char c = this.customerCode.charAt(i);
300	            if (c < '0' || c > '9') {
301	                continue;
302	            }
303	            int digit = c - '0';
304	            if (doubleDigit) {
305	                digit *= 2;
306	                if (digit > 9) {
307	                    digit -= 9;
308	                }
309	            }
310	            sum += digit;
311	            doubleDigit = !doubleDigit;
312	        }
313	        return (10 - (sum % 10)) % 10;
314	    }
315	
316	    /**
317	     * Return the owner's membership number, formatted {@code '<customerCode>-M<YY>'}
318	     * where {@code YY} is the last two digits of the registration date's year (for
319	     * example {@code 'SMI-0007-M26'}). Returns {@code null} when either the customer
320	     * code or the registration date is not set.
321	     */
322	    public String getMembershipNumber() {
323	        if (this.customerCode == null || this.registrationDate == null) {
324	            return null;
325	        }
326	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
327	    }
328	
329	    public String getHouseholdId() {
330	        return this.householdId;
331	    }
332	
333	    public void setHouseholdId(String householdId) {
334	        this.householdId = householdId;
335	    }
336	
337	    public Integer getNamesakeCount() {
338	        return this.namesakeCount;
339	    }
340	
341	    /**
342	     * Return the owner's membership points, the raw score from which the
343	     * membership level is derived. Starting at {@code 0}, add {@code 2} when an
344	     * email address is present, {@code 1} when the owner has no namesakes
345	     * (namesake count is {@code 0}), {@code 2} for a household of {@code 3} or
346	     * more, and {@code 3} when the owner's tenure (days since the registration
347	     * date) exceeds {@code 365}.
348	     */
349	    public Integer getMembershipPoints() {
350	        int points = 0;
351	        boolean hasEmail = this.email != null && !this.email.isBlank();
352	        if (hasEmail) {
353	            points += 2;
354	        }
355	        if (this.namesakeCount != null && this.namesakeCount == 0) {
356	            points += 1;
357	        }
358	        if (this.householdSize != null && this.householdSize >= 3) {
359	            points += 2;
360	        }
361	        if (this.registrationDate != null
362	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
363	            points += 3;
364	        }
365	        return points;
366	    }
367	
368	    /**
369	     * Return the owner's membership level, a number from {@code 1} to {@code 4},
370	     * derived from {@link #getMembershipPoints()}: {@code 1} for {@code 0-1}
371	     * points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
372	     * {@code 4} for {@code 6} or more.
373	     */
374	    public Integer getMembershipLevel() {
375	        int points = getMembershipPoints();
376	        if (points >= 6) {
377	            return 4;
378	        }
379	        if (points >= 4) {
380	            return 3;
381	        }
382	        if (points >= 2) {
383	            return 2;
384	        }
385	        return 1;
386	    }
387	
388	    public void setNamesakeCount(Integer namesakeCount) {
389	        this.namesakeCount = namesakeCount;
390	    }
391	
392	    public Integer getHouseholdSize() {
393	        return this.householdSize;
394	    }
395	
396	    public void setHouseholdSize(Integer householdSize) {
397	        this.householdSize = householdSize;
398	    }
399	
400	    /**
401	     * Whether this owner, when created, softly matched an existing owner by
402	     * sharing the same last name and postcode but with a different telephone.
403	     * Such an owner is still created; the flag surfaces the likely duplication.
404	     */
405	    public Boolean getPossibleDuplicate() {
406	        return this.possibleDuplicate;
407	    }
408	
409	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
410	        this.possibleDuplicate = possibleDuplicate;
411	    }
412	
413	    /**
414	     * The id of the existing owner this owner softly matched on last name and
415	     * postcode (with a different telephone), or {@code null} when there is no
416	     * such match.
417	     */
418	    public Integer getPossibleDuplicateOf() {
419	        return this.possibleDuplicateOf;
420	    }
421	
422	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
423	        this.possibleDuplicateOf = possibleDuplicateOf;
424	    }
425	
426	    /**
427	     * Whether more than 80 owners had already been registered on this owner's
428	     * registration day at the time it was created, flagging a bulk-signup surge.
429	     */
430	    public Boolean getBulkSignupWarning() {
431	        return this.bulkSignupWarning;
432	    }
433	
434	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
435	        this.bulkSignupWarning = bulkSignupWarning;
436	    }
437	
438	    /**
439	     * Return the owner's locality (region), preferring the postcode: when the
440	     * postcode is present and falls within a known region's inclusive range
441	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), that
442	     * region is returned. Otherwise the value falls back to the fixed
443	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
444	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the
445	     * table. This yields the same region for known cities but disambiguates
446	     * cities that share a name.
447	     */
448	    public String getLocality() {
449	        String regionFromPostcode = regionForPostcode();
450	        if (regionFromPostcode != null) {
451	            return regionFromPostcode;
452	        }
453	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
454	    }
455	
456	    /**
457	     * Return the owner's IANA timezone, derived from the locality/region via the
458	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
459	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or
460	     * {@code null} when the region is not in the table.
461	     */
462	    public String getTimezone() {
463	        return REGION_TIMEZONE.get(getLocality());
464	    }
465	
466	    /**
467	     * Look up the region whose inclusive postcode range contains this owner's
468	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
469	     * known range.
470	     */
471	    private String regionForPostcode() {
472	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
473	            return null;
474	        }
475	        int value = Integer.parseInt(this.postcode);
476	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
477	            int[] range = entry.getValue();
478	            if (value >= range[0] && value <= range[1]) {
479	                return entry.getKey();
480	            }
481	        }
482	        return null;
483	    }
484	
485	    /**
486	     * Return the owner's preferred contact channel, derived from the stored
487	     * contact details: {@code 'EMAIL'} when an email address is present,
488	     * otherwise {@code 'PHONE'}.
489	     */
490	    public String getContactPreference() {
491	        boolean hasEmail = this.email != null && !this.email.isBlank();
492	        return hasEmail ? "EMAIL" : "PHONE";
493	    }
494	
495	    /**
496	     * Return the owner's derived identity key, which consolidates all duplicate
497	     * detection into a single value formed as
498	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}.
499	     * The telephone and email are already stored in their normalized (E.164 /
500	     * lower-cased) forms; a missing email or household id contributes an empty
501	     * segment. A create is rejected only when a new owner's whole identity key
502	     * equals an existing owner's.
503	     */
504	    public String getIdentityKey() {
505	        String telephonePart = this.telephone == null ? "" : this.telephone;
506	        String emailPart = (this.email == null) ? "" : this.email;
507	        String householdPart = (this.householdId == null) ? "" : this.householdId;
508	        return telephonePart + "|" + emailPart + "|" + householdPart;
509	    }
510	
511	    protected Set<Pet> getPetsInternal() {
512	        if (this.pets == null) {
513	            this.pets = new HashSet<>();
514	        }
515	        return this.pets;
516	    }
517	
518	    protected void setPetsInternal(Set<Pet> pets) {
519	        this.pets = pets;
520	    }
521	
522	    public List<Pet> getPets() {
523	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
524	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
525	        return Collections.unmodifiableList(sortedPets);
526	    }
527	
528	    public void setPets(List<Pet> pets) {
529	        this.pets = new HashSet<>(pets);
530	    }
531	
532	    public void addPet(Pet pet) {
533	        getPetsInternal().add(pet);
534	        pet.setOwner(this);
535	    }
536	
537	    /**
538	     * Return the Pet with the given name, or null if none found for this Owner.
539	     *
540	     * @param name to test
541	     * @return true if pet name is already in use
542	     */
543	    public Pet getPet(String name) {
544	        return getPet(name, false);
545	    }
546	
547	    /**
548	     * Return the Pet with the given name, or null if none found for this Owner.
549	     *
550	     * @param name to test
551	     * @return true if pet name is already in use
552	     */
553	    public Pet getPet(String name, boolean ignoreNew) {
554	        name = name.toLowerCase();
555	        for (Pet pet : getPetsInternal()) {
556	            if (!ignoreNew || !pet.isNew()) {
557	                String compName = pet.getName();
558	                compName = compName.toLowerCase();
559	                if (compName.equals(name)) {
560	                    return pet;
561	                }
562	            }
563	        }
564	        return null;
565	    }
566	
567	    public Pet getPet(Integer petId) {
568	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
569	    }
570	
571	    @Override
572	    public String toString() {
573	        return new ToStringCreator(this)
574	
575	            .append("id", this.getId())
576	            .append("new", this.isNew())
577	            .append("lastName", this.getLastName())
578	            .append("firstName", this.getFirstName())
579	            .append("address", this.address)
580	            .append("city", this.city)
581	            .append("telephone", this.telephone)
582	            .append("email", this.email)
583	            .toString();
584	    }
585	}
