114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
119	        if (normalizedTelephone == null) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
123	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        if (isDisposableEmailDomain(ownerFieldsDto.getEmail())) {
127	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
128	        }
129	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
130	        owner.setTelephone(normalizedTelephone);
131	        if (!owner.isPostcodeValidForCity()) {
132	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
133	        }
134	        // The household id is deterministic: it is derived purely from the owner's
135	        // (last name, postcode), so every owner at the same last name and postcode resolves
136	        // to the same value. It is assigned up front, before any duplicate detection, so the
137	        // identity key and the household check below both key off it.
138	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
139	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
140	        // Consolidated hard-duplicate detection: reject only when the new owner's WHOLE
141	        // identityKey (telephone|email|householdId) equals an existing owner's. With the
142	        // household id now computed up front, two members of one household still differ here
143	        // whenever their telephone or email differs, and so are both allowed.
144	        String identityKey = owner.getIdentityKey();
145	        if (this.clinicService.findAllOwners().stream()
146	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
147	            return new ResponseEntity<>(HttpStatus.CONFLICT);
148	        }
149	        // Household duplicate: because the household is keyed on (last name, postcode), any
150	        // existing owner sharing this computed household id is the same household. A second
151	        // such owner is rejected as a household duplicate (409) unless it explicitly declares
152	        // 'sharesHousehold', which now only bypasses this block (the link is no longer created
153	        // here — the id is computed).
154	        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
155	        if (!householdMembers.isEmpty() && !sharesHousehold) {
156	            return new ResponseEntity<>(HttpStatus.CONFLICT);
157	        }
158	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
159	            return new ResponseEntity<>(HttpStatus.CONFLICT);
160	        }
161	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
162	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
163	        }
164	        LocalDate effectiveDate =
165	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
166	        LocalDate registrationDate = toBusinessDay(effectiveDate);
167	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
168	        if (ownersRegisteredToday >= 100) {
169	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
170	        }
171	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
172	        HttpHeaders headers = new HttpHeaders();
173	        owner.setRegistrationDate(registrationDate);
174	        owner.setCustomerCode(customerCode(owner));
175	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
176	        owner.setBulkSignupWarning(bulkSignupWarning);
177	        // The household size (an input to the membership computation) keys off the computed
178	        // household id: this owner plus everyone already sharing it.
179	        owner.setHouseholdSize(householdMembers.size() + 1);
180	        // Soft-match ("possible duplicate"): a declared household member is not a suspected
181	        // duplicate, so only a non-declared create is scored. In practice a non-declared owner
182	        // sharing an existing owner's last name and postcode is already rejected above as a
183	        // household duplicate, so this now only ever confirms the owner is not a duplicate.
184	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
185	        owner.setPossibleDuplicate(possibleDuplicate != null);
186	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
187	        this.clinicService.saveOwner(owner);
188	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
189	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
190	            owner.getMembershipNumber());
191	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
192	        headers.setLocation(UriComponentsBuilder.newInstance()
193	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
194	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
195	    }
