280	
281	
282	    /**
283	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
284	     * stripped. When a leading {@code '+'} and country code are present they are kept;
285	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
286	     * is dropped from the national digits. The result must be a {@code '+'} followed
287	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
288	     * is returned to signal a bad request.
289	     */
290	    /**
291	     * Build the customer code for a newly created owner, formatted
292	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived from the
293	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
294	     * derivation the locality uses), and {@code HASH8} is the first eight upper-case
295	     * hex characters of the SHA-256 of the owner's normalized telephone concatenated
296	     * with its last name. This identity carries no sequence number.
297	     */
298	    private String customerCode(Owner owner) {
299	        String region = owner.getLocality();
300	        String hash8 = customerCodeHash(owner.getTelephone(), owner.getLastName());
301	        String base = region + "-" + hash8;
302	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
303	            .map(Owner::getCustomerCode)
304	            .filter(java.util.Objects::nonNull)
305	            .collect(java.util.stream.Collectors.toSet());
306	        if (!existing.contains(base)) {
307	            return base;
308	        }
309	        int n = 2;
310	        while (existing.contains(base + "-" + n)) {
311	            n++;
312	        }
313	        return base + "-" + n;
314	    }
315	
316	    /**
317	     * Compute the {@code HASH8} portion of a customer code: the first eight upper-case
318	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
319	     * treated as empty when {@code null}), already in their normalized forms.
320	     */
321	    private String customerCodeHash(String telephone, String lastName) {
322	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
323	        try {
324	            byte[] digest = MessageDigest.getInstance("SHA-256")
325	                .digest(key.getBytes(StandardCharsets.UTF_8));
326	            StringBuilder sb = new StringBuilder();
327	            for (int i = 0; i < 4; i++) {
328	                sb.append(String.format("%02X", digest[i]));
329	            }
330	            return sb.toString();
331	        }
332	        catch (NoSuchAlgorithmException e) {
333	            throw new IllegalStateException(e);
334	        }
335	    }
336	
337	    /**
338	     * Count the existing owners whose city matches the given one, compared after
339	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
340	     * cap: a city that already holds this many owners is at capacity.
341	     */
342	    private long countOwnersInCity(String city) {
343	        String normalizedCity = normalizeForHousehold(city);
344	        return this.clinicService.findAllOwners().stream()
345	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
346	            .count();
347	    }
348	
349	    /**
350	     * Count the existing owners whose registration date falls on the given day. Used to
351	     * enforce the per-day create limit: once this many owners have been registered today,
352	     * the day is at capacity and further creates are rejected.
353	     */
354	    private long countOwnersRegisteredOn(LocalDate day) {
355	        return this.clinicService.findAllOwners().stream()
356	            .filter(existing -> day.equals(existing.getRegistrationDate()))
357	            .count();
358	    }
359	
360	    /**
361	     * Roll a registration date forward to the next business day: a date falling on a
362	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
363	     * returned unchanged.
364	     */
365	    private LocalDate toBusinessDay(LocalDate date) {
366	        DayOfWeek dayOfWeek = date.getDayOfWeek();
367	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
368	            return date.plusDays(8 - dayOfWeek.getValue());
369	        }
370	        return date;
371	    }
372	
373	    /**
374	     * Find the existing owners that already belong to the same household as the given
375	     * computed household id. Because the household id is derived deterministically from
376	     * the owner's (last name, postcode), this is exactly the set of other owners sharing
377	     * that last name and postcode.
378	     */
379	    private List<Owner> findHouseholdMembers(String householdId) {
380	        if (householdId == null) {
381	            return List.of();
382	        }
383	        return this.clinicService.findAllOwners().stream()
384	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
385	            .toList();
386	    }
387	
388	    /**
389	     * Find an existing owner that this new owner softly duplicates: one sharing the same
390	     * last name (compared case-insensitively after whitespace normalization) and the same
391	     * postcode, but with a different telephone. Returns the lowest-id such owner, or
392	     * {@code null} when the new owner has no postcode or no soft match exists. Owners
393	     * whose telephone equals the new owner's are excluded, as those are governed by the
394	     * hard-duplicate (identityKey) check rather than this soft match.
395	     */
396	    private Owner findPossibleDuplicate(Owner owner) {
397	        String postcode = owner.getPostcode();
398	        if (postcode == null) {
399	            return null;
400	        }
401	        String normalizedLastName = normalizeForHousehold(owner.getLastName());
402	        String telephone = owner.getTelephone();
403	        return this.clinicService.findAllOwners().stream()
404	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
405	                && postcode.equals(existing.getPostcode())
406	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
407	            .min(java.util.Comparator.comparing(Owner::getId))
408	            .orElse(null);
409	    }
410	
411	    /**
412	     * Count the existing owners that already share both the given first and last
413	     * name, compared case-insensitively. Used to populate an owner's namesake count
414	     * at creation time, reflecting how many owners with the same name existed before
415	     * this one was created.
416	     */
417	    private int countNamesakes(String firstName, String lastName) {
418	        String normalizedFirstName = normalizeName(firstName);
419	        String normalizedLastName = normalizeName(lastName);
420	        return (int) this.clinicService.findAllOwners().stream()
421	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
422	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
423	            .count();
424	    }
425	
426	    private String normalizeName(String value) {
427	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
428	    }
429	
430	    /**
431	     * Build the deterministic identifier shared by all owners of one household: the first
432	     * 12 hex characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}.
433	     * Because it depends only on the (last name, postcode) pair, every owner at the same last
434	     * name and postcode resolves to the same value regardless of creation order.
435	     */
436	    private String householdId(String lastName, String postcode) {
437	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
438	        try {
439	            byte[] digest = MessageDigest.getInstance("SHA-256")
440	                .digest(key.getBytes(StandardCharsets.UTF_8));
441	            StringBuilder sb = new StringBuilder();
442	            for (int i = 0; i < 6; i++) {
443	                sb.append(String.format("%02x", digest[i]));
444	            }
445	            return sb.toString();
446	        }
447	        catch (NoSuchAlgorithmException e) {
448	            throw new IllegalStateException(e);
449	        }
450	    }
451	
452	    private String normalizeForHousehold(String value) {
453	        if (value == null) {
454	            return "";
455	        }
456	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
457	    }
458	
459	    /** True when the email's domain is on the disposable-provider blocklist. */
460	    private boolean isDisposableEmailDomain(String email) {
461	        if (email == null) {
462	            return false;
463	        }
464	        int at = email.lastIndexOf('@');
465	        if (at < 0 || at == email.length() - 1) {
466	            return false;
467	        }
468	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
469	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
470	    }
471	
472	    private String normalizeTelephone(String telephone) {
473	        if (telephone == null) {
474	            return null;
475	        }
476	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
477	        String digits;
478	        if (cleaned.startsWith("+")) {
479	            digits = cleaned.substring(1);
480	        } else {
481	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
482	            digits = "61" + national;
483	        }
484	        if (!digits.matches("[0-9]{8,15}")) {
485	            return null;
486	        }
487	        if (!hasValidNationalLength(digits)) {
488	            return null;
489	        }
490	        return "+" + digits;
491	    }
492	
493	    /**
